#pragma once
#include "ksArpEventTask.h"
#include "ksPartControlTasks.h"
#include "ksNativeKeyService.h"
#include "ksNativeArpEmissionService.h"
#include <optional>
#include <type_traits>
namespace ks {
// Queue expiry, held-key gate policy and queued note release form one closed
// transaction. The retained outputs are musical bindings and the most recent
// MIDI/voice transactions, rather than processor operands or an event history.
class NativeArpGateService final {
public:
 enum class Kind{Gate,DirectGate,Append};enum class Component{Event,Gate,Lookup,Held,Off};
 struct Input{uint8_t part=0;uint16_t noteVelocity=0;};struct Effect{bool read=false,write=false;};
 struct GateResult{uint8_t state=0,voices=0,shape=0,count=0;uint16_t phase=0,expiry=0;bool bound=false,stateRead=false,phaseRead=false,held=false,voicesRead=false,shapeRead=false,loop=false;};
 struct DomainOutputs{unsigned events=0,lastNoteEvent=0,lastVelocityEvent=0,lastReleaseEvent=0,lastPatchEvent=0,lastMidiEvent=0;uint8_t note=0,policy=0,comparedPolicy=0,mask=0;uint16_t velocityNote=0,midiEvent=0,releasedAddress=0,releasedAge=0;uint32_t releasedPort=0,patch=0;bool voice=false,released=false,patchObserved=false,midi=false,lastPolicyObserved=false,comparisonPolicy=false;std::optional<NativeVoiceReleaseService>lastVoice;};
 struct Summary{Input input{};uint8_t part=0;bool appendGate=false;GateResult gate{};DomainOutputs outputs{};};
 NativeArpGateService(Kind k,Input in):kind_(k),parent_(k==Kind::Gate?ArpEventTask::Kind::Gate:k==Kind::DirectGate?ArpEventTask::Kind::DirectGate:ArpEventTask::Kind::Append,in.part,uint8_t(in.noteVelocity),uint8_t(in.noteVelocity>>8)){summary_.input=in;summary_.part=in.part;choose(Component::Event);}
 Kind kind()const{return kind_;}bool complete()const{return complete_;}bool critical()const{return component_==Component::Off&&off_->critical();}Component component()const{return component_;}uint32_t components()const{return components_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}const ArpEventTask&event()const{return parent_;}const ArpEventTask&gate()const{return gate_?*gate_:parent_;}const NativeKeyService*held()const{return held_?&*held_:nullptr;}
 uint32_t expressionSourceAfter(uint32_t prior)const{if(!complete_)throw std::logic_error("Incomplete gate expression binding");const auto&o=summary_.outputs;if(o.released)prior=o.releasedPort;if(o.lastVelocityEvent>o.lastReleaseEvent)prior=(prior&0xffff0000u)|o.velocityNote;if(o.lastNoteEvent>o.lastVelocityEvent&&o.lastNoteEvent>o.lastReleaseEvent)prior=(prior&0xffffff00u)|o.note;if(kind_==Kind::Append&&summary_.appendGate)prior=(prior&0xffff0000u)|summary_.input.noteVelocity;return prior;}
 uint32_t notificationAfter(uint32_t prior)const{if(!complete_)throw std::logic_error("Incomplete gate notification binding");const auto&o=summary_.outputs;const uint16_t retained=uint16_t(prior);if(o.patchObserved)prior=o.patch;if(o.lastMidiEvent>o.lastPatchEvent)prior=(prior&0xffff0000u)|o.midiEvent;if(kind_==Kind::Append&&summary_.appendGate)prior=(prior&0xffff0000u)|retained;return prior;}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,NativeArpGateService>)return this;else if constexpr(std::is_same_v<T,ArpEventTask>)return component_==Component::Event?&parent_:component_==Component::Gate?&*gate_:component_==Component::Off?off_->template task<T>():nullptr;else if constexpr(std::is_same_v<T,PartLookupTask>){if(component_==Component::Lookup)return &*lookup_;if(component_==Component::Held)return held_->template task<T>();if(component_==Component::Off)return off_->template task<T>();return nullptr;}else {if(component_==Component::Held)return held_->template task<T>();if(component_==Component::Off)return off_->template task<T>();return nullptr;}}
 unsigned nextClocks(int previous=-1)const{if(complete_)return 0;if(component_==Component::Off)return off_->nextClocks(previous);if(component_==Component::Held)return held_->nextClocks(previous);if(component_==Component::Lookup)return lookup_->stage()==PartLookupTask::Stage::Complete?17:lookup_->nextClocks();const auto&t=current();return t.nextClocks(t.publication()?byteClock(target(t,t.stage()),previous):3);}
 template<class R,class W>unsigned advanceBefore(unsigned available,R&&read,W&&write,int previous=-1){const auto cost=nextClocks(previous);if(!cost||available<cost)return 0;effect_={};
  if(component_==Component::Off){off_->advanceBefore(cost,read,write,previous);effect_={off_->effect().read,off_->effect().write};if(off_->complete()){observeOff();activeEvent().resumeChild();choose(gate_?Component::Gate:Component::Event);}return cost;}
  if(component_==Component::Held){held_->advanceBefore(cost,read,write,previous);effect_={held_->effect().read,held_->effect().write};if(held_->complete()){summary_.gate.held=true;summary_.part=held_->summary().part;activeEvent().resumeHeld(summary_.part,held_->summary().activity!=0);choose(gate_?Component::Gate:Component::Event);}return cost;}
  if(component_==Component::Lookup){if(lookup_->stage()==PartLookupTask::Stage::Complete){effect_.read=true;summary_.part=lookup_->index();summary_.gate.bound=true;activeEvent().resumePart(summary_.part);choose(gate_?Component::Gate:Component::Event);}else lookup_->advanceBefore(cost,[&](PartLookupTask::Layout){return read(0x17526,cost);});return cost;}
  using T=ArpEventTask;using S=T::Stage;auto&t=current();const auto stage=t.stage();const auto base=0x160d2u+334*t.part();const auto get=[&](uint32_t a,unsigned n,unsigned back=0){a&=0xffffff;if(a<0x15000||a+n>0x30000)throw std::logic_error("Unsupported arp gate observation");uint32_t v=0;for(unsigned i=0;i<n;++i)v=(v<<8)|uint8_t(read(a+i,cost-back-3*((n-i-1+(a+i)%2)/2)));return v;};
  t.advanceBefore(cost,[&](S q)->uint32_t{auto&g=summary_.gate;switch(q){case S::AppendReadMode:return get(base+324,1);case S::AppendReadCount:case S::AppendReadIndex:return get(base+320,1);case S::AppendReadState:return get(base+311,1);case S::AppendReadPhase:return get(base+304,2);case S::AppendReadDuration:return get(base+12,2);case S::GateReadState:g.stateRead=true;return g.state=uint8_t(get(base+311,1));case S::GateReadPhase:g.phaseRead=true;return g.phase=uint16_t(get(base+304,2));case S::GateReadExpiry:return g.expiry=uint16_t(get(base+14,2));case S::GateReadVoices:g.voicesRead=true;return g.voices=uint8_t(get(base+313,1));case S::GateReadShape:g.shapeRead=true;return g.shape=uint8_t(get(base+330,1));case S::GateReadCount:g.loop=true;return g.count=uint8_t(get(base+312,1));case S::GateReadNote:{auto&o=summary_.outputs;o.lastNoteEvent=++o.events;o.note=uint8_t(get(base+16+t.cursor(),1,2));return o.note;}default:throw std::logic_error("Unsupported arp gate stage");}},[&](S q,uint32_t v){const auto at=target(t,q);const unsigned n=q==S::AppendPublishExpiry?2:1;for(unsigned i=0;i<n;++i)write(at+i,uint8_t(v>>(8*(n-i-1))),cost-3*((n-i-1+(at+i)%2)/2));},[&](S q){return byteClock(target(t,q),previous);});
  switch(stage){case S::AppendRetainNote:case S::AppendRetainPatch:case S::AppendReleaseGate:case S::GateBindPart:case S::GateScanHeld:case S::GateRetainCursor:case S::GateRetainCount:case S::GateRetainPart:case S::GateReleaseNote:effect_.write=true;break;case S::AppendReleasePatch:case S::AppendReleaseNote:case S::AppendFinish:case S::GateReleasePart:case S::GateReleaseCount:case S::GateReleaseCursor:case S::GateFinish:case S::OffFinish:effect_.read=true;break;default:break;}
  if(t.awaitingChild()){switch(t.child()){case T::Child::Part:lookup_.emplace(PartLookupTask::Layout::Parameters);choose(Component::Lookup);break;case T::Child::Held:held_.emplace(NativeKeyService::Kind::Held);choose(Component::Held);break;case T::Child::ReleaseGate:summary_.appendGate=true;gate_.emplace(T::Kind::DirectGate,t.part(),t.note(),t.velocity());choose(Component::Gate);break;case T::Child::Off:off_.emplace(NativeArpEmissionService::Kind::Off,NativeArpEmissionService::Input{t.part(),uint16_t(t.note())});choose(Component::Off);break;default:throw std::logic_error("Unsupported arp gate child");}}
  else if(t.complete()){if(component_==Component::Gate){parent_.resumePart(t.part());summary_.part=t.part();choose(Component::Event);}else complete_=true;}return cost;
 }
private:
 ArpEventTask&activeEvent(){return gate_?*gate_:parent_;}ArpEventTask&current(){return component_==Component::Gate?*gate_:parent_;}const ArpEventTask&current()const{return component_==Component::Gate?*gate_:parent_;}
 static unsigned byteClock(uint32_t a,int p){return !(p&1)&&a==(uint32_t(p)|1u)?0:3;}
 static uint32_t target(const ArpEventTask&t,ArpEventTask::Stage s){using S=ArpEventTask::Stage;const auto base=0x160d2u+334*t.part();switch(s){case S::AppendPublishExpiry:return base+14;case S::AppendPublishNote:return base+16+t.queueCount();case S::AppendPublishCount:return base+320;case S::AppendPublishMirror:case S::GatePublishEmpty:return base+312;default:return base+311;}}
 void observeOff(){auto&o=summary_.outputs;const auto&v=off_->summary();o.mask=v.mask;o.policy=v.policy;o.lastPolicyObserved=v.policyObserved;if(off_->midi()){o.midi=true;o.lastMidiEvent=++o.events;o.midiEvent=off_->midi()->summary().event;o.lastVelocityEvent=o.lastMidiEvent;o.velocityNote=uint16_t((64u<<8)|off_->event().note());}if(off_->release()){o.voice=true;o.lastVoice=*off_->release();const auto&r=*off_->release();if(r.patchObserved()){o.patchObserved=true;o.lastPatchEvent=++o.events;o.patch=r.lastPatch();}if(r.releasedAny()){o.released=true;o.lastReleaseEvent=++o.events;o.releasedPort=r.dspPort();o.releasedAddress=r.lastAddress();o.releasedAge=r.lastReleaseAge();}o.comparisonPolicy=false;}else if(v.policyObserved){o.comparisonPolicy=true;o.comparedPolicy=v.policy;}}
 void choose(Component c){component_=c;components_|=1u<<unsigned(c);}
 Kind kind_;ArpEventTask parent_;Summary summary_{};Component component_=Component::Event;Effect effect_{};bool complete_=false;uint32_t components_=0;std::optional<ArpEventTask>gate_;std::optional<PartLookupTask>lookup_;std::optional<NativeKeyService>held_;std::optional<NativeArpEmissionService>off_;
};
}
